import rospy
from typing import Type, Callable, TYPE_CHECKING
from ..logger.logger import logger

if TYPE_CHECKING:
    from .node import ROS1Node


class ROS1Subscriber:
    def __init__(
        self,
        node: "ROS1Node",
        msg_type: Type,
        topic: str,
        callback: Callable,
        qos_profile: int = 10,
        **kwargs
    ):
        """
        创建ROS1订阅者

        Args:
            node: ROS1Node实例
            msg_type: 消息类型
            topic: 话题名称
            callback: 回调函数
            qos_profile: 队列大小（对应ROS2的qos_profile）
            **kwargs: 其他参数传递给rospy.Subscriber
        """
        self._node = node
        self._msg_type = msg_type
        self._topic = topic
        self._callback = callback
        self._subscriber = rospy.Subscriber(
            topic, msg_type, callback, queue_size=qos_profile, **kwargs
        )

    @property
    def topic(self) -> str:
        """获取话题名称"""
        return self._topic

    @property
    def msg_type(self) -> Type:
        """获取消息类型"""
        return self._msg_type

    def destroy(self):
        """销毁订阅者"""
        self._subscriber.unregister()
